using System;
using UnityEngine;
using UnityEngine.Rendering;

namespace DistantLands.Cozy.Blocks
{
    //Screenspace
    [System.Serializable]
    public class SunshaftsScreenspaceOverride : BlockOverride
    {
        public override string Title => "Screenspace";
        public override string Category => "Sunshafts";
        public override bool FeatureEnabledGlobally => CozyPreferences.CurrentStyle.UseSunshaftsScreenspace;
        public override void ToggleFeature() => CozyPreferences.CurrentStyle.ToggleSunshaftsScreenspace();

        /// <summary>
        /// Set the color of the sunshafts
        /// </summary>
        [CozySearchable]
        [Tooltip("Set the color of the sunshafts")]
        [BlockProperty(VarType.Color, "Color")]
        public BlockColorValue color = new BlockColorValue(default);
        /// <summary>
        /// Set the brightness of the sunshafts
        /// </summary>
        [CozySearchable]
        [Tooltip("Set the brightness of the sunshafts")]
        [BlockProperty(VarType.Float, "Intensity", minFloat = 0, maxFloat = 1)]
        public BlockFloatValue intensity = new BlockFloatValue(default);
        /// <summary>
        /// Blurs the sunshafts to sets the length
        /// </summary>
        [CozySearchable]
        [Tooltip("Blurs the sunshafts to sets the length")]
        [BlockProperty(VarType.Float, "Length", minFloat = 0, maxFloat = 1)]
        public BlockFloatValue length = new BlockFloatValue(default);
        /// <summary>
        /// Set the step count
        /// </summary>
        [CozySearchable]
        [Tooltip("Set the step count")]
        [BlockProperty(VarType.Float, "Steps")]
        public BlockFloatValue steps = new BlockFloatValue(default);
        /// <summary>
        /// How strongly do clouds occlude sunrays
        /// </summary>
        [CozySearchable]
        [Tooltip("How strongly do clouds occlude sunrays")]
        [BlockProperty(VarType.Float, "CloudMaskAmount", minFloat = 0, maxFloat = 1)]
        public BlockFloatValue cloudMaskAmount = new BlockFloatValue(default);

        public override bool CaptureFromParameters(AtmosphereParameters parameters) {
            color = new BlockColorValue(parameters.sunshaftsScreenspaceColor);
            intensity = new BlockFloatValue(parameters.sunshaftsScreenspaceIntensity);
            length = new BlockFloatValue(parameters.sunshaftsScreenspaceLength);
            steps = new BlockFloatValue(parameters.sunshaftsScreenspaceSteps);
            cloudMaskAmount = new BlockFloatValue(parameters.sunshaftsScreenspaceCloudMaskAmount);
            return true;
        }

        public override void ApplyToWeatherSphere(AtmosphereParameters parameters, float weight) {
            if (!active || !FeatureEnabledGlobally) return;
            if (!color.disabled)
                parameters.sunshaftsScreenspaceColor.Lerp(color.value, weight);
            if (!intensity.disabled)
                parameters.sunshaftsScreenspaceIntensity.Lerp(intensity.value, weight);
            if (!length.disabled)
                parameters.sunshaftsScreenspaceLength.Lerp(length.value, weight);
            if (!steps.disabled)
                parameters.sunshaftsScreenspaceSteps.Lerp(steps.value, weight);
            if (!cloudMaskAmount.disabled)
                parameters.sunshaftsScreenspaceCloudMaskAmount.Lerp(cloudMaskAmount.value, weight);
        }
    }


